/**
 * Unit tests for getGhCreateCommands in lib/gh-command.ts
 *
 * A gh create call inside a shell conditional or loop must still be found:
 * the reserved word (`if`, `while`, `until`, `elif`, `!`, plus `then`, `else`,
 * `do`) holds the executable slot, and the real command follows it. Codex HOLD
 * on #5362 at 98d179b1.
 */

import { describe, it, expect } from 'vitest';
import { getGhCreateCommands } from '../../lib/gh-command.js';

const find = (command: string) => getGhCreateCommands(command, '--label', '-l');

describe('getGhCreateCommands: gh create behind a shell reserved word', () => {
  const cases: [string, string][] = [
    ['if', 'if gh issue create --title "x"; then echo ok; fi'],
    ['while', 'while gh issue create --title "x"; do break; done'],
    ['until', 'until gh issue create --title "x"; do sleep 1; done'],
    ['!', '! gh issue create --title "x"'],
    ['if !', 'if ! gh issue create --title "x"; then echo failed; fi'],
    ['elif', 'if false; then :; elif gh issue create --title "x"; then :; fi'],
    ['then', 'if true; then gh issue create --title "x"; fi'],
    ['else', 'if false; then :; else gh issue create --title "x"; fi'],
    ['do', 'for i in 1 2; do gh issue create --title "x"; done'],
  ];

  for (const [name, command] of cases) {
    it(`finds the create after ${name}, no label`, () => {
      expect(find(command)).toEqual([{ kind: 'issue', hasFlag: false }]);
    });
  }

  it('finds a pr create after if', () => {
    expect(find('if gh pr create --title "x"; then :; fi')).toEqual([{ kind: 'pr', hasFlag: false }]);
  });

  it('reads the label flag after if', () => {
    expect(find('if gh issue create --title "x" --label bug; then :; fi')).toEqual([
      { kind: 'issue', hasFlag: true },
    ]);
    expect(find('if gh issue create --title "x" --label=bug; then :; fi')).toEqual([
      { kind: 'issue', hasFlag: true },
    ]);
  });

  it('works with env and a variable prefix after the reserved word', () => {
    expect(find('if FOO=1 env gh issue create --title "x"; then :; fi')).toEqual([
      { kind: 'issue', hasFlag: false },
    ]);
  });
});

describe('getGhCreateCommands: controls that must stay unmatched', () => {
  it('a non-gh command after if stays unmatched', () => {
    expect(find('if git issue create --title "x"; then :; fi')).toEqual([]);
    expect(find('if echo issue create; then :; fi')).toEqual([]);
  });

  it('gh named as an argument, not the executable, stays unmatched', () => {
    expect(find('if echo gh issue create; then :; fi')).toEqual([]);
    expect(find('echo if gh issue create')).toEqual([]);
  });

  it('a reserved word inside a quoted payload stays unmatched', () => {
    expect(find('echo "if gh issue create --title x"')).toEqual([]);
  });

  it('gh issue list behind if is not a create', () => {
    expect(find('if gh issue list; then :; fi')).toEqual([]);
  });

  it('the plain create is still found', () => {
    expect(find('gh issue create --title "x"')).toEqual([{ kind: 'issue', hasFlag: false }]);
  });
});

// Shapes taken from this machine: `rtk rewrite` turns `gh issue create` into
// `rtk gh issue create`, and agents wrap long calls in timeout, sudo, nohup, time, xargs.
describe('getGhCreateCommands: gh create behind a wrapper command', () => {
  const wrapped: [string, string][] = [
    ['rtk', 'rtk gh issue create --title "x"'],
    ['rtk by full path', '/opt/homebrew/bin/rtk gh issue create --title "x"'],
    ['rtk proxy', 'rtk proxy gh issue create --title "x"'],
    ['timeout', 'timeout 30 gh issue create --title "x"'],
    ['timeout with options', 'timeout -k 5 30 gh issue create --title "x"'],
    ['sudo', 'sudo gh issue create --title "x"'],
    ['sudo -u', 'sudo -u deploy gh issue create --title "x"'],
    ['time', 'time gh issue create --title "x"'],
    ['nohup', 'nohup gh issue create --title "x"'],
    ['nice', 'nice -n 10 gh issue create --title "x"'],
    ['xargs', 'xargs -I {} gh issue create --title "x"'],
    ['env -i', 'env -i gh issue create --title "x"'],
    ['env -u and an assignment', 'env -u FOO BAR=1 gh issue create --title "x"'],
    ['command', 'command gh issue create --title "x"'],
    ['exec', 'exec gh issue create --title "x"'],
    ['two wrappers', 'rtk timeout 30 gh issue create --title "x"'],
    ['wrapper after a pipe', 'echo hi | rtk gh issue create --title "x"'],
    ['backticks', 'echo `gh issue create --title "x"`'],
    ['command substitution', 'echo $(gh issue create --title "x")'],
  ];

  it('lists wrapped cases', () => {
    expect(wrapped.length).toBeGreaterThan(10);
  });

  for (const [name, command] of wrapped) {
    it(`finds the create behind ${name}, no label`, () => {
      expect(find(command)).toEqual([{ kind: 'issue', hasFlag: false }]);
    });
  }

  it('reads the label flag behind a wrapper', () => {
    expect(find('rtk gh issue create --title "x" --label bug')).toEqual([{ kind: 'issue', hasFlag: true }]);
    expect(find('timeout 30 gh issue create --title "x" -l bug')).toEqual([{ kind: 'issue', hasFlag: true }]);
  });

  it('finds a pr create behind a wrapper', () => {
    expect(find('rtk gh pr create --title "x"')).toEqual([{ kind: 'pr', hasFlag: false }]);
  });

  it('does not match when the wrapped command is not gh', () => {
    const notGh = [
      'rtk git issue create --title "x"',
      'sudo git issue create',
      'timeout 30 echo gh issue create',
      'nohup echo gh issue create &',
      'xargs echo gh issue create',
      'env -i FOO=1 git status',
      'rtk gh issue list',
      'timeout 30 gh issue view 5',
      'sudo',
      'rtk',
    ];
    expect(notGh.length).toBeGreaterThan(5);
    for (const command of notGh) expect(find(command), command).toEqual([]);
  });

  it('does not treat a wrapper name in an argument position as a wrapper', () => {
    expect(find('echo rtk gh issue create')).toEqual([]);
    expect(find('git commit -m "rtk gh issue create"')).toEqual([]);
  });
});

describe('getGhCreateCommands: gh create inside a string a shell runs', () => {
  const nested: [string, string][] = [
    ['bash -c', 'bash -c "gh issue create --title x"'],
    ['sh -c', "sh -c 'gh issue create --title x'"],
    ['zsh -lc', 'zsh -lc "gh issue create --title x"'],
    ['/bin/bash -c', '/bin/bash -c "gh issue create --title x"'],
    ['eval one string', 'eval "gh issue create --title x"'],
    ['eval words', 'eval gh issue create --title x'],
    ['bash -c with a wrapper inside', 'bash -c "rtk gh issue create --title x"'],
    ['bash -c with a conditional inside', 'bash -c "if gh issue create --title x; then :; fi"'],
  ];

  it('lists nested cases', () => {
    expect(nested.length).toBeGreaterThan(5);
  });

  for (const [name, command] of nested) {
    it(`finds the create in ${name} and marks it nested`, () => {
      expect(find(command)).toEqual([{ kind: 'issue', hasFlag: false, nested: true }]);
    });
  }

  it('reads the label flag inside the string', () => {
    expect(find('bash -c "gh issue create --title x --label bug"')).toEqual([
      { kind: 'issue', hasFlag: true, nested: true },
    ]);
  });

  it('a plain create is not marked nested', () => {
    expect(find('rtk gh issue create --title x')[0]).not.toHaveProperty('nested');
  });

  it('does not match when the string runs another command', () => {
    const quiet = [
      'bash -c "echo gh issue create"',
      'bash -c "git issue create"',
      'bash script.sh gh issue create',
      'bash -c "gh issue list"',
      'eval echo gh issue create',
      'bash -c',
      'eval',
    ];
    expect(quiet.length).toBeGreaterThan(5);
    for (const command of quiet) expect(find(command), command).toEqual([]);
  });
});

describe('getGhCreateCommands: quotes that used to disable the parser', () => {
  it('an apostrophe in a trailing comment does not hide the create', () => {
    expect(find("gh issue create --title x # don't forget")).toEqual([{ kind: 'issue', hasFlag: false }]);
  });

  it('an apostrophe in a comment on an earlier line does not hide the create', () => {
    expect(find("# it's the second call\ngh issue create --title x")).toEqual([{ kind: 'issue', hasFlag: false }]);
  });

  it('a heredoc body with an apostrophe does not hide a create after it', () => {
    const command = "cat > /tmp/b.md <<'EOF'\nit's a body\nEOF\ngh issue create --title x --body-file /tmp/b.md";
    expect(find(command)).toEqual([{ kind: 'issue', hasFlag: false }]);
  });

  it('a create written inside a heredoc body is data and stays unmatched', () => {
    const command = "cat > /tmp/b.md <<'EOF'\ngh issue create --title x\nEOF";
    expect(find(command)).toEqual([]);
  });

  it('a hash inside a word is not a comment', () => {
    expect(find('gh issue create --title a#b --label bug')).toEqual([{ kind: 'issue', hasFlag: true }]);
  });

  it('a truly unterminated quote still returns nothing (pinned: a rewrite would land inside the quote)', () => {
    expect(find('gh issue create --title "unterminated')).toEqual([]);
  });
});
